"use client";

import { useRef, useEffect } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { reasonsILoveYou } from '@/data/reasons';

gsap.registerPlugin(ScrollTrigger);

export default function ReasonsScene() {
  const containerRef = useRef<HTMLDivElement>(null);
  const itemsRef = useRef<(HTMLDivElement | null)[]>([]);

  useEffect(() => {
    const mm = gsap.matchMedia();

    mm.add("(min-width: 768px)", () => {
      // Desktop: Staggered reveal as you scroll down
      itemsRef.current.forEach((item, index) => {
        if (!item) return;

        gsap.fromTo(item,
          { opacity: 0, y: 50 },
          {
            opacity: 1,
            y: 0,
            duration: 1,
            ease: "power2.out",
            scrollTrigger: {
              trigger: item,
              start: "top 80%",
            }
          }
        );
      });
    });

    mm.add("(max-width: 767px)", () => {
      // Mobile: simpler fade in
      itemsRef.current.forEach((item) => {
        if (!item) return;
        gsap.fromTo(item,
          { opacity: 0 },
          {
            opacity: 1,
            duration: 1,
            scrollTrigger: {
              trigger: item,
              start: "top 85%",
            }
          }
        );
      });
    });

    return () => {
      mm.revert(); // Reverts media queries and scroll triggers
    };
  }, []);

  return (
    <section ref={containerRef} className="py-32 px-6 bg-warm-ivory text-deep-burgundy">
      
      <div className="max-w-4xl mx-auto text-center mb-24">
        <h2 className="text-4xl md:text-6xl font-serif leading-tight">
          Little Things<br/>I Love About You
        </h2>
      </div>

      <div className="max-w-5xl mx-auto flex flex-col gap-16 md:gap-24">
        {reasonsILoveYou.map((reason, index) => (
          <div 
            key={reason.id} 
            ref={el => { itemsRef.current[index] = el; }}
            className={`flex flex-col md:flex-row gap-8 md:gap-16 items-center ${index % 2 !== 0 ? 'md:flex-row-reverse' : ''}`}
          >
            {/* Number and Title */}
            <div className="w-full md:w-1/2 flex flex-col">
              <span className="text-muted-gold font-serif text-5xl md:text-7xl opacity-50 mb-4">
                {reason.number}
              </span>
              <h3 className="text-2xl md:text-4xl font-serif mb-4">
                {reason.title}
              </h3>
              <p className="text-deep-burgundy/70 text-lg leading-relaxed font-light">
                {reason.description}
              </p>
            </div>

            {/* Optional Image */}
            <div className="w-full md:w-1/2 flex justify-center">
              {reason.imagePath ? (
                <div className="relative w-full max-w-sm aspect-square md:aspect-[3/4] overflow-hidden rounded-sm border border-deep-burgundy/10 shadow-xl">
                   <div className="absolute inset-0 bg-deep-burgundy/5 mix-blend-overlay z-10" />
                   <div className="w-full h-full bg-[#e8ddd0] flex items-center justify-center text-deep-burgundy/30 text-sm tracking-widest border border-dashed border-deep-burgundy/20">
                     [ {reason.title.toUpperCase()} MEDIA ]
                   </div>
                </div>
              ) : (
                <div className="w-full max-w-sm aspect-video md:aspect-[3/4] flex items-center justify-center opacity-30">
                   <div className="w-16 h-[1px] bg-deep-burgundy/30" />
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

    </section>
  );
}
