"use client";

import { useState, useRef, useEffect } from 'react';
import { galleryImages, GalleryImage } from '@/data/gallery';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { X } from 'lucide-react'; // Make sure to install lucide-react if not present, but we will use a raw SVG or simple close button if not available.

gsap.registerPlugin(ScrollTrigger);

export default function GalleryScene() {
  const [selectedImage, setSelectedImage] = useState<GalleryImage | null>(null);
  const galleryRef = useRef<HTMLDivElement>(null);
  const itemsRef = useRef<(HTMLDivElement | null)[]>([]);

  useEffect(() => {
    // Parallax or subtle reveal effect on gallery items
    itemsRef.current.forEach((item, index) => {
      if (!item) return;
      gsap.fromTo(item,
        { opacity: 0, y: 40 },
        {
          opacity: 1,
          y: 0,
          duration: 0.8,
          ease: "power2.out",
          scrollTrigger: {
            trigger: item,
            start: "top 90%",
          }
        }
      );
    });

    return () => {
      ScrollTrigger.getAll().forEach(t => t.kill());
    };
  }, []);

  // Use a simple escape key listener for lightbox
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setSelectedImage(null);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  return (
    <section ref={galleryRef} className="py-32 px-4 md:px-8 bg-midnight text-warm-ivory min-h-screen relative">
      
      <div className="max-w-7xl mx-auto mb-20 text-center">
        <h2 className="text-4xl md:text-6xl font-serif mb-6">Fragments of Us</h2>
        <p className="text-warm-ivory/60 max-w-2xl mx-auto font-light text-lg">
          A collection of moments frozen in time.
        </p>
      </div>

      {/* Masonry-ish Grid via Columns */}
      <div className="max-w-7xl mx-auto columns-1 sm:columns-2 md:columns-3 gap-6 space-y-6">
        {galleryImages.map((image, i) => (
          <div 
            key={image.id}
            ref={el => { itemsRef.current[i] = el; }}
            className="break-inside-avoid cursor-pointer group relative overflow-hidden rounded-md border border-warm-ivory/10 bg-warm-ivory/5"
            onClick={() => setSelectedImage(image)}
          >
            {/* Aspect ratio placeholder using padding trick if we wanted, but let's use a simpler approach */}
            <div 
              style={{ paddingBottom: `${(image.height || 100) / (image.width || 100) * 100}%` }}
              className="relative w-full overflow-hidden"
            >
              <div className="absolute inset-0 bg-[#1a1a24] flex items-center justify-center text-warm-ivory/30 text-xs tracking-wider transition-transform duration-700 group-hover:scale-105">
                 [ IMG: {image.alt} ]
              </div>
              <div className="absolute inset-0 bg-deep-burgundy/60 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-center justify-center mix-blend-overlay" />
            </div>
          </div>
        ))}
      </div>

      {/* Lightbox */}
      {selectedImage && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-midnight/95 backdrop-blur-xl p-4 md:p-12">
          <button 
            onClick={() => setSelectedImage(null)}
            className="absolute top-6 right-6 text-warm-ivory/60 hover:text-warm-ivory transition-colors z-50 p-2"
            aria-label="Close"
          >
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <line x1="18" y1="6" x2="6" y2="18"></line>
              <line x1="6" y1="6" x2="18" y2="18"></line>
            </svg>
          </button>
          
          <div className="relative max-w-5xl w-full max-h-[85vh] h-full flex flex-col items-center justify-center">
            {/* Lightbox Image Placeholder */}
            <div className="w-full h-full border-2 border-warm-ivory/10 bg-[#1a1a24] flex items-center justify-center text-warm-ivory/30 shadow-2xl">
              [ HI-RES: {selectedImage.alt} ]
            </div>
            {selectedImage.caption && (
              <p className="absolute bottom-4 text-center text-warm-ivory font-serif italic text-lg drop-shadow-md">
                {selectedImage.caption}
              </p>
            )}
          </div>
        </div>
      )}

    </section>
  );
}
