"use client";

import { useRef, useEffect } from 'react';
import { videoMemories } from '@/data/videos';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

export default function VideoScene() {
  const containerRef = useRef<HTMLDivElement>(null);
  const scrollWrapperRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Horizontal scroll effect on desktop
    const mm = gsap.matchMedia();

    mm.add("(min-width: 1024px)", () => {
      if (scrollWrapperRef.current && containerRef.current) {
        const sections = gsap.utils.toArray('.video-panel');
        
        gsap.to(sections, {
          xPercent: -100 * (sections.length - 1),
          ease: "none",
          scrollTrigger: {
            trigger: containerRef.current,
            pin: true,
            scrub: 1,
            snap: 1 / (sections.length - 1),
            end: () => "+=" + scrollWrapperRef.current?.offsetWidth
          }
        });
      }
    });

    return () => {
      mm.revert();
    };
  }, []);

  return (
    <section ref={containerRef} className="bg-warm-ivory text-deep-burgundy overflow-hidden relative">
      
      {/* Title overlay */}
      <div className="absolute top-12 left-0 right-0 text-center z-10 pointer-events-none px-6">
        <h2 className="text-3xl md:text-5xl font-serif text-deep-burgundy">
          Moments in Motion
        </h2>
      </div>

      <div 
        ref={scrollWrapperRef} 
        className="flex flex-col lg:flex-row w-full lg:w-[300vw] lg:h-screen pt-32 lg:pt-0"
      >
        {videoMemories.map((video, index) => (
          <div 
            key={video.id} 
            className="video-panel w-full lg:w-screen h-[50vh] lg:h-screen flex items-center justify-center p-6 lg:p-24 shrink-0 relative"
          >
            <div className="w-full max-w-4xl aspect-video bg-midnight/5 border-2 border-deep-burgundy/10 rounded-lg shadow-2xl relative overflow-hidden group">
              {/* Fake video placeholder */}
              <div className="absolute inset-0 flex items-center justify-center bg-[#e8ddd0]">
                <div className="text-center">
                  <div className="w-16 h-16 rounded-full border-2 border-deep-burgundy/40 flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform cursor-pointer">
                    <div className="w-0 h-0 border-t-[8px] border-t-transparent border-l-[12px] border-l-deep-burgundy border-b-[8px] border-b-transparent ml-1" />
                  </div>
                  <p className="text-sm tracking-widest text-deep-burgundy/60 uppercase">Play Video</p>
                </div>
              </div>
            </div>
            
            <div className="absolute bottom-6 lg:bottom-16 left-6 lg:left-24">
              <span className="text-muted-gold font-serif text-2xl mb-1 block">0{index + 1}</span>
              <h3 className="text-2xl font-serif">{video.title}</h3>
              {video.caption && <p className="text-deep-burgundy/70 mt-1">{video.caption}</p>}
            </div>
          </div>
        ))}
      </div>
      
    </section>
  );
}
