"use client";

import { useRef, useEffect } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

export default function LoveLetterScene() {
  const containerRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Parallax scrolling for the text
    gsap.fromTo(textRef.current,
      { y: 100, opacity: 0 },
      {
        y: 0,
        opacity: 1,
        ease: "power2.out",
        scrollTrigger: {
          trigger: containerRef.current,
          start: "top 70%",
          end: "bottom 80%",
          scrub: 1,
        }
      }
    );

    return () => {
      ScrollTrigger.getAll().forEach(t => t.kill());
    };
  }, []);

  return (
    <section ref={containerRef} className="py-32 px-6 md:px-12 bg-midnight text-warm-ivory relative flex justify-center items-center min-h-[80vh]">
      
      {/* Decorative background elements */}
      <div className="absolute inset-0 pointer-events-none overflow-hidden">
        <div className="absolute -top-[20%] -right-[10%] w-[50%] h-[50%] bg-deep-burgundy/10 rounded-full blur-[120px]" />
        <div className="absolute -bottom-[20%] -left-[10%] w-[50%] h-[50%] bg-muted-gold/10 rounded-full blur-[120px]" />
      </div>

      <div ref={textRef} className="max-w-3xl mx-auto relative z-10 text-center md:text-left">
        <div className="mb-12 flex justify-center md:justify-start">
          <div className="w-12 h-[1px] bg-muted-gold" />
        </div>
        
        <h2 className="text-3xl md:text-5xl font-serif text-muted-gold mb-8 italic">
          My Dearest Diya,
        </h2>
        
        <div className="space-y-6 text-lg md:text-2xl font-light leading-relaxed text-warm-ivory/80 font-serif">
          <p>
            When I started building this, I realized that no amount of code, animations, or words could truly capture what you mean to me.
          </p>
          <p>
            You are the quiet peace at the end of a long day and the sudden burst of laughter that catches me off guard. You are my favorite thought.
          </p>
          <p>
            As you celebrate another year of life, I want to celebrate another year of having you in mine. I promise to keep choosing you, every single day.
          </p>
        </div>

        <div className="mt-16 text-right">
          <p className="text-xl italic font-serif text-warm-ivory">Yours always,</p>
          <p className="text-3xl font-serif text-muted-gold mt-2">Baby</p>
        </div>
      </div>
      
    </section>
  );
}
